package com.c016.pushupflappy.game.zone

import android.content.res.Resources
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import com.c016.pushupflappy.R

/** Original pastel pixel art generated by tools/pastel_art.py. */
class ZoneSprites(resources: Resources) {
    private val res = resources

    private fun load(id: Int): Bitmap = BitmapFactory.decodeResource(res, id)

    /** Faces right; mirrored when flying left. */
    val ship = listOf(load(R.drawable.zone_ship_1), load(R.drawable.zone_ship_2))
    val base = listOf(load(R.drawable.zone_base_1), load(R.drawable.zone_base_2))
    val puff = listOf(load(R.drawable.zone_puff_1), load(R.drawable.zone_puff_2))

    /** Faces left; mirrored when flying right. */
    val bee = listOf(load(R.drawable.zone_bee_1), load(R.drawable.zone_bee_2))
    val coin = listOf(load(R.drawable.zone_coin_1), load(R.drawable.zone_coin_2))
    val reverse = load(R.drawable.zone_reverse)
    val shop = load(R.drawable.zone_shop)
    val bomb = load(R.drawable.zone_bomb)

    /** Eyes open, then blinking. */
    val boss = listOf(load(R.drawable.zone_boss_1), load(R.drawable.zone_boss_2))
    val heart = listOf(load(R.drawable.zone_heart_1), load(R.drawable.zone_heart_2))
    val pop = listOf(load(R.drawable.zone_pop_1), load(R.drawable.zone_pop_2), load(R.drawable.zone_pop_3))
}
